// Snapshot the live Supabase override tables (pack_overrides, level_overrides,
// achievement_overrides) into function-plane/src/overrides-snapshot.js so the
// app ships with the correct level data baked in and never has to trust its
// built-in fallbacks when offline.
//
// Run before every release build, then commit the regenerated file:
//   npm run snapshot:data
//
// Reads SUPABASE_URL / SUPABASE_ANON_KEY straight out of supabase-config.js —
// no extra configuration needed. Requires Node 18+ (global fetch).
const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, '..', 'function-plane', 'src');

function readConfig() {
  const cfg = fs.readFileSync(path.join(SRC, 'supabase-config.js'), 'utf8');
  const url = cfg.match(/SUPABASE_URL\s*=\s*'([^']+)'/)?.[1];
  const key = cfg.match(/SUPABASE_ANON_KEY\s*=\s*'([^']+)'/)?.[1];
  if (!url || !key) throw new Error('Could not read SUPABASE_URL / SUPABASE_ANON_KEY from supabase-config.js');
  return { url, key };
}

async function fetchTable({ url, key }, table, tolerateMissing = false) {
  const res = await fetch(`${url}/rest/v1/${table}?select=*`, {
    headers: { apikey: key, Authorization: `Bearer ${key}` },
  });
  if (!res.ok) {
    const body = await res.text();
    if (tolerateMissing && res.status === 404) return [];
    if (tolerateMissing && /does not exist|relation/i.test(body)) return [];
    throw new Error(`${table}: HTTP ${res.status} ${body.slice(0, 200)}`);
  }
  return res.json();
}

(async () => {
  const cfg = readConfig();
  console.log(`Fetching override tables from ${cfg.url} ...`);
  const [packs, levels, achievements] = await Promise.all([
    fetchTable(cfg, 'pack_overrides'),
    fetchTable(cfg, 'level_overrides'),
    fetchTable(cfg, 'achievement_overrides', /*tolerateMissing*/ true),
  ]);

  // Deterministic ordering keeps regenerated snapshots diff-friendly
  packs.sort((a, b) => String(a.pack_id).localeCompare(String(b.pack_id)));
  levels.sort((a, b) =>
    String(a.pack_id).localeCompare(String(b.pack_id)) || (a.level_index - b.level_index));
  achievements.sort((a, b) => String(a.id).localeCompare(String(b.id)));

  const data = { packs, levels, achievements };
  const out =
    '// AUTO-GENERATED by scripts/snapshot-overrides.js — do not edit by hand.\n' +
    '// Baked-in state of the Supabase override tables at build time, so the\n' +
    '// app boots with correct level data even with no network. Regenerate\n' +
    '// before every release: npm run snapshot:data\n' +
    `// Generated: ${new Date().toISOString()}\n` +
    'window.FP_OVERRIDES_SNAPSHOT = ' + JSON.stringify({ data }, null, 1) + ';\n';

  const outPath = path.join(SRC, 'overrides-snapshot.js');
  fs.writeFileSync(outPath, out);
  console.log(`Wrote ${outPath}`);
  console.log(`  packs: ${packs.length}, levels: ${levels.length}, achievements: ${achievements.length}`);
  console.log('Commit the regenerated file together with your release.');
})().catch(e => { console.error('snapshot-overrides failed:', e.message); process.exit(1); });
